(4847977, 703439, 80904, '<td valign="top">man very creative. Shame on the lighting</td>', 'man very creative. Shame on the lighting', '2008-07-28 14:11:34.000000', NULL, 1),
(4847978, 703692, 91663, '<td valign="top">haha, awesome concept. Don''t quite understand why she''d be in her bra, but Awesome nonetheless. Excellent execution nonetheless. 8</td>', 'haha, awesome concept. Don''t quite understand why she''d be in her bra, but Awesome nonetheless. Excellent execution nonetheless. 8', '2008-07-28 14:12:06.000000', NULL, 1),
(4847979, 703469, 83313, '<td valign="top">I like the</td>', 'I like the', '2008-07-28 14:12:18.000000', NULL, 1),
(4847981, 703700, 91663, '<td valign="top">Looks a little snapshottish. A little more blacks would help get rid of the washed-out look this has, I think. Also, the leaves and plants behind them look a bit oversharpened and way brighter than your subject to the point of distraction.<br/>Best of luck!</td>', 'Looks a little snapshottish. A little more blacks would help get rid of the washed-out look this has, I think. Also, the leaves and plants behind them look a bit oversharpened and way brighter than your subject to the point of distraction.Best of luck!', '2008-07-28 14:13:47.000000', NULL, 1),
(4847982, 702730, 83313, '<td valign="top">Working? Struck me as the package delivered while you were out at lunch. I like the selective color usage.</td>', 'Working? Struck me as the package delivered while you were out at lunch. I like the selective color usage.', '2008-07-28 14:14:02.000000', NULL, 1),
(4847985, 703723, 91663, '<td valign="top">Very cool setup, but could use a good deal more contrast--there''s no part of this b/w image that is actually white--as a rule, try to adjust to make sure that happens.</td>', 'Very cool setup, but could use a good deal more contrast--there''s no part of this b/w image that is actually white--as a rule, try to adjust to make sure that happens.', '2008-07-28 14:14:52.000000', NULL, 1),
(4847987, 703536, 83313, '<td valign="top">A scary image, though the table and wall appear too clean and perfect for the dark concept being conveyed.</td>', 'A scary image, though the table and wall appear too clean and perfect for the dark concept being conveyed.', '2008-07-28 14:15:57.000000', NULL, 1),
(4847988, 703529, 91663, '<td valign="top">Nice choice of focus and DOF. Would like to see a different composition, though--maybe landscape orientation with the woman occupying a different lateral position than the box. Still, 7 for what you''ve done here.</td>', 'Nice choice of focus and DOF. Would like to see a different composition, though--maybe landscape orientation with the woman occupying a different lateral position than the box. Still, 7 for what you''ve done here.', '2008-07-28 14:16:31.000000', NULL, 1),
(4847989, 702961, 83313, '<td valign="top">Is that how they come now? Anything can be ordered online these days. I had to get mine the old fashioned way.</td>', 'Is that how they come now? Anything can be ordered online these days. I had to get mine the old fashioned way.', '2008-07-28 14:17:01.000000', NULL, 1),
(4847992, 702342, 91663, '<td valign="top">This tells a pretty cool story. Great processing. As a side note, I know the frustration of freckling easily, but never considered taking refuge from the sun in a box :P<br/>8</td>', 'This tells a pretty cool story. Great processing. As a side note, I know the frustration of freckling easily, but never considered taking refuge from the sun in a box :P8', '2008-07-28 14:17:35.000000', NULL, 1),
(4847994, 703746, 83313, '<td valign="top">Very abstract and very, very good. Lots of subtle details and shadows for the eye to explore. An 8 and a fave.</td>', 'Very abstract and very, very good. Lots of subtle details and shadows for the eye to explore. An 8 and a fave.', '2008-07-28 14:18:47.000000', NULL, 1),
(4847995, 703532, 83313, '<td valign="top">It''s a kitty toy!</td>', 'It''s a kitty toy!', '2008-07-28 14:19:46.000000', NULL, 1),
(4847997, 703126, 83313, '<td valign="top">Now that''s different! Wonder if there''s a story behind this. Almost looks like a performance of some kind.</td>', 'Now that''s different! Wonder if there''s a story behind this. Almost looks like a performance of some kind.', '2008-07-28 14:20:52.000000', NULL, 1),
