INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4848870, 702346, 69192, '<td valign="top">Nice lighting!</td>', 'Nice lighting!', '2008-07-29 00:42:41.000000', NULL, 1),
(4848872, 703651, 69192, '<td valign="top">Seems like the cat should be more in focus than the box.</td>', 'Seems like the cat should be more in focus than the box.', '2008-07-29 00:42:59.000000', NULL, 1),
(4848873, 703469, 69192, '<td valign="top">Interesting idea!</td>', 'Interesting idea!', '2008-07-29 00:43:10.000000', NULL, 1),
(4848875, 703684, 69192, '<td valign="top">Very different!  Very nice!</td>', 'Very different!  Very nice!', '2008-07-29 00:43:25.000000', NULL, 1),
(4848877, 703532, 69192, '<td valign="top">Wow!  I''m curious how you got so lucky that this animal was carrying a cardboard box just when you needed it to.  Funny that a ton of other people used kitties in boxes - you''ve got the mega cat with a box!</td>', 'Wow!  I''m curious how you got so lucky that this animal was carrying a cardboard box just when you needed it to.  Funny that a ton of other people used kitties in boxes - you''ve got the mega cat with a box!', '2008-07-29 00:44:43.000000', NULL, 1),
(4848878, 703745, 69192, '<td valign="top">Interesting picture!  Nice composition!</td>', 'Interesting picture!  Nice composition!', '2008-07-29 00:45:17.000000', NULL, 1),
(4848881, 703737, 69192, '<td valign="top">Awww, that would be horrible!  The lighting could definitely be improved on this one!</td>', 'Awww, that would be horrible!  The lighting could definitely be improved on this one!', '2008-07-29 00:45:55.000000', NULL, 1),
(4848882, 703000, 69192, '<td valign="top">Funny, I''ve never seen a cardboard box trying to hitch a ride. =)</td>', 'Funny, I''ve never seen a cardboard box trying to hitch a ride. =)', '2008-07-29 00:46:19.000000', NULL, 1),
(4848884, 702228, 69192, '<td valign="top">This picture kind of gives me the creeps!  Looks like little spider legs inside the cardboard.</td>', 'This picture kind of gives me the creeps!  Looks like little spider legs inside the cardboard.', '2008-07-29 00:46:46.000000', NULL, 1),
(4848908, 703692, 53316, '<td valign="top">I love everything except the bra - maybe if she were more in the box and you couldn''t see the bottom of the bra it would look like a lacey wedding dress? Otherwise I think this is well-done and quite creative, and I love the writing on the box as I think it adds to the meaning of a person being in the box.</td>', 'I love everything except the bra - maybe if she were more in the box and you couldn''t see the bottom of the bra it would look like a lacey wedding dress? Otherwise I think this is well-done and quite creative, and I love the writing on the box as I think it adds to the meaning of a person being in the box.', '2008-07-29 01:07:43.000000', NULL, 1),
(4848951, 703651, 89940, '<td valign="top">Pretty kitty but he''s out of focus. It''s really important to get the eyes in focus in a photo like this.</td>', 'Pretty kitty but he''s out of focus. It''s really important to get the eyes in focus in a photo like this.', '2008-07-29 02:19:43.000000', NULL, 1),
(4848954, 702074, 89940, '<td valign="top">I''m not sure what it is about this photo but I spend a lot of time looking at the heart trying to figure out what it is made of instead of enjoying the photo. The composition is nice, I like the flower, but the heart itself just doesn''t do it for me.</td>', 'I''m not sure what it is about this photo but I spend a lot of time looking at the heart trying to figure out what it is made of instead of enjoying the photo. The composition is nice, I like the flower, but the heart itself just doesn''t do it for me.', '2008-07-29 02:20:58.000000', NULL, 1),
(4848955, 703069, 30490, '<td valign="top">Wow, really great concept AND execution!  Nice job!</td>', 'Wow, really great concept AND execution!  Nice job!', '2008-07-29 02:21:42.000000', NULL, 1),
(4848956, 703179, 30490, '<td valign="top">Yes, he is definately "thinking" and is inside a box... I get it!  What is it about cats and boxes... they seem to go together better than cats and cream!  Beautiful image of a beautiful cat!</td>', 'Yes, he is definately "thinking" and is inside a box... I get it!  What is it about cats and boxes... they seem to go together better than cats and cream!  Beautiful image of a beautiful cat!', '2008-07-29 02:23:24.000000', NULL, 1),
(4848958, 703676, 30490, '<td valign="top">Too cute!  Just a hint of mischief in his eyes!</td>', 'Too cute!  Just a hint of mischief in his eyes!', '2008-07-29 02:24:22.000000', NULL, 1),
(4848960, 703692, 30490, '<td valign="top">Great concept and execution!  Love the lighting!</td>', 'Great concept and execution!  Love the lighting!', '2008-07-29 02:25:04.000000', NULL, 1),
(4848961, 702892, 30490, '<td valign="top">Oh My God!  They are just too cute!  At least I don''t think they are the same kitten!  Great photo!</td>', 'Oh My God!  They are just too cute!  At least I don''t think they are the same kitten!  Great photo!', '2008-07-29 02:25:15.000000', NULL, 1),
(4848962, 703532, 30490, '<td valign="top">And I thought my little puddy cat liked to play with boxes... Whoa! that''s a GREAT BIG CAT playing with a box! Don''t think I would mess with her box! Wonder where this was taken... can''t wait to see the info on this image!</td>', 'And I thought my little puddy cat liked to play with boxes... Whoa! that''s a GREAT BIG CAT playing with a box! Don''t think I would mess with her box! Wonder where this was taken... can''t wait to see the info on this image!', '2008-07-29 02:25:19.000000', NULL, 1),
(4848963, 703709, 89940, '<td valign="top">Great photo. Great DOF, I really like how sharp the red crayon is compared to the others. Perhaps a little too much negative space on the left side but that''s a minor issue.</td>', 'Great photo. Great DOF, I really like how sharp the red crayon is compared to the others. Perhaps a little too much negative space on the left side but that''s a minor issue.', '2008-07-29 02:25:25.000000', NULL, 1),
