(4848968, 702702, 30490, '<td valign="top">So they think, but a lot goes on in the devious mind of a cat.... Very nice image!</td>', 'So they think, but a lot goes on in the devious mind of a cat.... Very nice image!', '2008-07-29 02:26:48.000000', NULL, 1),
(4848970, 703745, 30490, '<td valign="top">Oh those cats love to chew cardboard boxes don''t they?? Good capture of the feline decorator at work!</td>', 'Oh those cats love to chew cardboard boxes don''t they?? Good capture of the feline decorator at work!', '2008-07-29 02:27:23.000000', NULL, 1),
