(4852274, 703528, 50695, '<td valign="top">Lovely, mindbending image. I give you my Posthumous Blue<br/> <br/><img alt="'' . substr(''//blackyak.com/dpc/bluepost.jpg'', strrpos(''//blackyak.com/dpc/bluepost.jpg'', ''/'') + 1) . ''" border="0" src="//blackyak.com/dpc/bluepost.jpg"/></td>', 'Lovely, mindbending image. I give you my Posthumous Blue ', '2008-07-30 22:44:13.000000', NULL, 1),
