(4852449, 702228, 51747, '<td valign="top">An interesting view of cardboard. Well done!</td>', 'An interesting view of cardboard. Well done!', '2008-07-30 23:44:11.000000', NULL, 1),
(4852450, 703555, 96614, '<td valign="top">Great Shot! I think your ISO was a little high because it came out a bit grainy, otherwise great pic!</td>', 'Great Shot! I think your ISO was a little high because it came out a bit grainy, otherwise great pic!', '2008-07-30 23:44:16.000000', NULL, 1),
(4852471, 703555, 51747, '<td valign="top">What a cute kitty! Just a little blurry. I''m sure you''ll do better next time! :)</td>', 'What a cute kitty! Just a little blurry. I''m sure you''ll do better next time! :)', '2008-07-30 23:50:51.000000', NULL, 1),
(4852479, 703363, 51747, '<td valign="top">Nice concept. Just needs to be sharper.</td>', 'Nice concept. Just needs to be sharper.', '2008-07-30 23:53:07.000000', NULL, 1),
(4852519, 703179, 25773, '<td valign="top">Brilliant! Favorite for me and my family!</td>', 'Brilliant! Favorite for me and my family!', '2008-07-31 00:09:13.000000', NULL, 1),
(4852525, 703194, 25773, '<td valign="top">It is too busy, and the box'' positioning does not even follow the rule of thirds... hard to find it</td>', 'It is too busy, and the box'' positioning does not even follow the rule of thirds... hard to find it', '2008-07-31 00:12:20.000000', NULL, 1),
(4852578, 703734, 53781, '<td valign="top">Being a military family and moving every 4 years or so I can so relate to this photograph!</td>', 'Being a military family and moving every 4 years or so I can so relate to this photograph!', '2008-07-31 00:36:25.000000', NULL, 1),
(4852586, 703349, 53781, '<td valign="top">Technically this is a great photo, however the model looks almost dead. I think had her eyes been open with some kind of facial expression it would have looked better.</td>', 'Technically this is a great photo, however the model looks almost dead. I think had her eyes been open with some kind of facial expression it would have looked better.', '2008-07-31 00:38:21.000000', NULL, 1),
(4852589, 703277, 53781, '<td valign="top">creepy yet cool...</td>', 'creepy yet cool...', '2008-07-31 00:39:49.000000', NULL, 1),
(4852608, 703356, 53781, '<td valign="top">The yellow seems a bit over saturated.</td>', 'The yellow seems a bit over saturated.', '2008-07-31 00:46:12.000000', NULL, 1),
(4852781, 703659, 77192, '<td valign="top">Thought no 1: Oh not another pic of a cute kitten in a box.<br/>Thought no 2: Oh I see it now! Fantastic.<br/> <br/>Really clever. 10 and favourited by me.</td>', 'Thought no 1: Oh not another pic of a cute kitten in a box.Thought no 2: Oh I see it now! Fantastic. Really clever. 10 and favourited by me.', '2008-07-31 02:37:03.000000', NULL, 1),
