(4852857, 703723, 95596, '<td valign="top">The idea is nice... but why is it so dark?</td>', 'The idea is nice... but why is it so dark?', '2008-07-31 05:54:22.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4852898, 702342, 96959, '<td valign="top">I love the atmosphere and claustrophobie of this shot</td>', 'I love the atmosphere and claustrophobie of this shot', '2008-07-31 07:14:46.000000', NULL, 1),
(4852933, 703532, 77192, '<td valign="top">This isn''t Andi, by any chance, is it? ;-)</td>', 'This isn''t Andi, by any chance, is it? ;-)', '2008-07-31 08:33:49.000000', NULL, 1),
(4852935, 703725, 77192, '<td valign="top">I''m really not sure about the idea of a tea light box made of cardboard lol.<br/> <br/>Quite nice though.</td>', 'I''m really not sure about the idea of a tea light box made of cardboard lol. Quite nice though.', '2008-07-31 08:35:51.000000', NULL, 1),
(4852938, 703118, 77192, '<td valign="top">lol funny. She won''t get much of a swing with a box over her though.</td>', 'lol funny. She won''t get much of a swing with a box over her though.', '2008-07-31 08:36:51.000000', NULL, 1),
(4852944, 703549, 77192, '<td valign="top">Yikes Mr Potato Head looks evil in that pic lol. Like Jack Nicholson in the shining. Title made me giggle too. :-)</td>', 'Yikes Mr Potato Head looks evil in that pic lol. Like Jack Nicholson in the shining. Title made me giggle too. :-)', '2008-07-31 08:40:20.000000', NULL, 1),
(4852950, 703692, 77192, '<td valign="top">lol clever idea.</td>', 'lol clever idea.', '2008-07-31 08:41:07.000000', NULL, 1),
(4852952, 703653, 77192, '<td valign="top">Clever idea, would like to have seen more origami than just the bird though</td>', 'Clever idea, would like to have seen more origami than just the bird though', '2008-07-31 08:41:54.000000', NULL, 1),
(4852955, 703733, 77192, '<td valign="top">He/She has gorgeous eyes :-) Very cute shot.</td>', 'He/She has gorgeous eyes :-) Very cute shot.', '2008-07-31 08:43:20.000000', NULL, 1),
(4852960, 703717, 77192, '<td valign="top">I''m assuming this was HDR? Good idea to shoot this that way but the greens have come out way too bright. I''d also like to see more colour in the sky.<br/> <br/>I like the shot a lot though. It conveys a very sad situation well. I particularly like the fact that the girl has her back to the camera, symbolising turning her back on her Dad.</td>', 'I''m assuming this was HDR? Good idea to shoot this that way but the greens have come out way too bright. I''d also like to see more colour in the sky. I like the shot a lot though. It conveys a very sad situation well. I particularly like the fact that the girl has her back to the camera, symbolising turning her back on her Dad.', '2008-07-31 08:46:43.000000', NULL, 1),
(4852964, 703458, 77192, '<td valign="top">Of all the animal-in-a-box shots (I think I counted 18) this one gets the prize for originality. So cute :-) nice one.</td>', 'Of all the animal-in-a-box shots (I think I counted 18) this one gets the prize for originality. So cute :-) nice one.', '2008-07-31 08:47:53.000000', NULL, 1),
(4852966, 702354, 77192, '<td valign="top">Lovely DOF. He/she looks so sad :-(</td>', 'Lovely DOF. He/she looks so sad :-(', '2008-07-31 08:48:23.000000', NULL, 1),
(4852971, 703069, 77192, '<td valign="top">This is definitely one of my favourites of the shot. Such a clever idea :-) There''s a nice range of poses and expressions. The fact you''ve lined up your boxes in a regular pattern means everybody is being seen and everyone gets equal precedence, unlike some group portraits.<br/> <br/>My only tiny nitpick (and it is a tiny one) is I''d like to see a few more people looking at the camera (perhaps one of the two people around the outside) I''d also like to see one or more older people in the shot to complete the "ages" theme.</td>', 'This is definitely one of my favourites of the shot. Such a clever idea :-) There''s a nice range of poses and expressions. The fact you''ve lined up your boxes in a regular pattern means everybody is being seen and everyone gets equal precedence, unlike some group portraits. My only tiny nitpick (and it is a tiny one) is I''d like to see a few more people looking at the camera (perhaps one of the two people around the outside) I''d also like to see one or more older people in the shot to complete the "ages" theme.', '2008-07-31 08:53:33.000000', NULL, 1),
(4853001, 703659, 96920, '<td valign="top">How adorable</td>', 'How adorable', '2008-07-31 09:29:41.000000', NULL, 1),
(4853114, 703730, 94957, '<td valign="top">Interesting perspective</td>', 'Interesting perspective', '2008-07-31 10:39:16.000000', NULL, 1),
(4853115, 703678, 94957, '<td valign="top">envokes emotion...hard to do with a cardboard box....7</td>', 'envokes emotion...hard to do with a cardboard box....7', '2008-07-31 10:40:20.000000', NULL, 1),
(4853118, 703069, 94957, '<td valign="top">very creative....7</td>', 'very creative....7', '2008-07-31 10:40:55.000000', NULL, 1),
(4853128, 703652, 94957, '<td valign="top">excellent...6</td>', 'excellent...6', '2008-07-31 10:41:47.000000', NULL, 1),
(4853251, 703309, 90495, '<td valign="top">So how many DMNC''s so far? lol Lovely shot of a common object. Detail is fantastic too, superb focus with good dof.</td>', 'So how many DMNC''s so far? lol Lovely shot of a common object. Detail is fantastic too, superb focus with good dof.', '2008-07-31 12:34:08.000000', NULL, 1),
(4853273, 703557, 24913, '<td valign="top">A winning photo for this challenge for sure. 10 Lovethe idea, and the monochromatic feel, with good use of DOF. Beautiful</td>', 'A winning photo for this challenge for sure. 10 Lovethe idea, and the monochromatic feel, with good use of DOF. Beautiful', '2008-07-31 12:48:22.000000', NULL, 1),
(4853287, 703069, 96924, '<td valign="top">Excellent!</td>', 'Excellent!', '2008-07-31 13:03:28.000000', NULL, 1),
(4853290, 703458, 90658, '<td valign="top">It seems a litte dark to me, but otherwise this is well done.</td>', 'It seems a litte dark to me, but otherwise this is well done.', '2008-07-31 13:06:17.000000', NULL, 1),
(4853291, 703730, 90658, '<td valign="top">Interesting composition.</td>', 'Interesting composition.', '2008-07-31 13:06:42.000000', NULL, 1),
(4853296, 703356, 90658, '<td valign="top">I really like that the yellow of labels is pretty much the same hue.  It adds visual continuity.</td>', 'I really like that the yellow of labels is pretty much the same hue.  It adds visual continuity.', '2008-07-31 13:07:30.000000', NULL, 1),
(4853297, 702957, 90658, '<td valign="top">Creative idea.  The colors seem slightly muted to me.</td>', 'Creative idea.  The colors seem slightly muted to me.', '2008-07-31 13:08:26.000000', NULL, 1),
(4853299, 703675, 90658, '<td valign="top">Art speaks differently to different people.</td>', 'Art speaks differently to different people.', '2008-07-31 13:08:54.000000', NULL, 1),
(4853302, 703456, 90658, '<td valign="top">This doesn''t seem "alive" to me.  Perhaps you were 1/2 second too early or too late with the shutter.  Look into Moe''s eyes, they seem lack-luster.  Nice idea though.</td>', 'This doesn''t seem "alive" to me.  Perhaps you were 1/2 second too early or too late with the shutter.  Look into Moe''s eyes, they seem lack-luster.  Nice idea though.', '2008-07-31 13:10:36.000000', NULL, 1),
(4853304, 703651, 90658, '<td valign="top">Art speaks differently to different people</td>', 'Art speaks differently to different people', '2008-07-31 13:10:56.000000', NULL, 1),
(4853305, 703733, 90658, '<td valign="top">Very playful shot with a very playful puppy!</td>', 'Very playful shot with a very playful puppy!', '2008-07-31 13:11:56.000000', NULL, 1),
(4853306, 703714, 90658, '<td valign="top">Just seems a little too dark.</td>', 'Just seems a little too dark.', '2008-07-31 13:12:14.000000', NULL, 1),
(4853307, 703676, 90658, '<td valign="top">I think a different background color would have really emphasized the stare of kitty.</td>', 'I think a different background color would have really emphasized the stare of kitty.', '2008-07-31 13:12:49.000000', NULL, 1),
(4853308, 703546, 90658, '<td valign="top">Seems a little noisy/grainy</td>', 'Seems a little noisy/grainy', '2008-07-31 13:13:15.000000', NULL, 1),
(4853309, 702074, 90658, '<td valign="top">This shot has intrigued me.  I think I''ve come back it to it about 4 times.</td>', 'This shot has intrigued me.  I think I''ve come back it to it about 4 times.', '2008-07-31 13:14:01.000000', NULL, 1),
(4853310, 702961, 90658, '<td valign="top">Interesting angle and compostion.  I actually like the fact that the toddler is looking off camera and interacting with something out of line of site.  It makes me wonder what is going on.</td>', 'Interesting angle and compostion.  I actually like the fact that the toddler is looking off camera and interacting with something out of line of site.  It makes me wonder what is going on.', '2008-07-31 13:15:15.000000', NULL, 1),
(4853311, 703557, 90658, '<td valign="top">Lots going on in the background.  Tonality is similar so you might get away with it with a little less backlight.</td>', 'Lots going on in the background.  Tonality is similar so you might get away with it with a little less backlight.', '2008-07-31 13:16:35.000000', NULL, 1),
(4853312, 702702, 90658, '<td valign="top">Interesting composition.  The cropping leaves me feeling that things are out of balance towards the top, but other than that...creative.</td>', 'Interesting composition.  The cropping leaves me feeling that things are out of balance towards the top, but other than that...creative.', '2008-07-31 13:17:44.000000', NULL, 1),
(4853313, 702600, 90658, '<td valign="top">This is simple and direct.  Thank you.</td>', 'This is simple and direct.  Thank you.', '2008-07-31 13:18:11.000000', NULL, 1),
(4853316, 703757, 90658, '<td valign="top">Definitely a creative twist on the challenge.  I kinda like the effect.</td>', 'Definitely a creative twist on the challenge.  I kinda like the effect.', '2008-07-31 13:19:26.000000', NULL, 1),
(4853321, 703725, 90658, '<td valign="top">Simple, yet effective.  The distinctive patterns within the box make this rather interesting.</td>', 'Simple, yet effective.  The distinctive patterns within the box make this rather interesting.', '2008-07-31 13:21:02.000000', NULL, 1),
(4853324, 702935, 90658, '<td valign="top">I''m just wondering about the color of the background.  The cream color of the box in front is sort of too similar and the clear plastic things don''t really stand out.  Of course, you probably have a different vision of this than I do.</td>', 'I''m just wondering about the color of the background.  The cream color of the box in front is sort of too similar and the clear plastic things don''t really stand out.  Of course, you probably have a different vision of this than I do.', '2008-07-31 13:23:00.000000', NULL, 1),
(4853326, 703118, 90658, '<td valign="top">This just sort of makes me smile.  There is so much expression in her little face.  Plus it reminds me of playing with ordinary boxes when I was that age.</td>', 'This just sort of makes me smile.  There is so much expression in her little face.  Plus it reminds me of playing with ordinary boxes when I was that age.', '2008-07-31 13:24:01.000000', NULL, 1),
(4853328, 703652, 90658, '<td valign="top">I like this.  There is humor, interest, depth even a little thought required on my part.  Well done.</td>', 'I like this.  There is humor, interest, depth even a little thought required on my part.  Well done.', '2008-07-31 13:24:47.000000', NULL, 1),
(4853333, 703700, 90658, '<td valign="top">This absolutely cracks me up.  Colors seem a bit washed out, but I don''t think this lends itself to the other HDR extreme.  Just a tad brighter.</td>', 'This absolutely cracks me up.  Colors seem a bit washed out, but I don''t think this lends itself to the other HDR extreme.  Just a tad brighter.', '2008-07-31 13:26:10.000000', NULL, 1),
(4853334, 703277, 90658, '<td valign="top">Freaky and well executed.</td>', 'Freaky and well executed.', '2008-07-31 13:26:41.000000', NULL, 1),
(4853335, 702354, 90658, '<td valign="top">I feel as if the cardboard was more of a tool used for an animal portrait; rather than creatively used to create a shot.  I''m not going to give you a DNMC as you obviously put thought into this and there is a box.<br/> <br/>Things seem a little too dark.</td>', 'I feel as if the cardboard was more of a tool used for an animal portrait; rather than creatively used to create a shot.  I''m not going to give you a DNMC as you obviously put thought into this and there is a box. Things seem a little too dark.', '2008-07-31 13:28:39.000000', NULL, 1),
(4853336, 703708, 90658, '<td valign="top">This just doesn''t POP!</td>', 'This just doesn''t POP!', '2008-07-31 13:29:29.000000', NULL, 1),
(4853341, 703469, 90658, '<td valign="top">Visually interesting.  Good use of color, excellent use of differing objects.  Lighting is interesting.  Textural differences, nice comp.  Technically, this is fabulous.  For me, personally, (subjective here) just not what tickles my fancy.  Still an 8 for the effort and technique.</td>', 'Visually interesting.  Good use of color, excellent use of differing objects.  Lighting is interesting.  Textural differences, nice comp.  Technically, this is fabulous.  For me, personally, (subjective here) just not what tickles my fancy.  Still an 8 for the effort and technique.', '2008-07-31 13:31:51.000000', NULL, 1),
(4853342, 702595, 90658, '<td valign="top">Definitely very creative.</td>', 'Definitely very creative.', '2008-07-31 13:32:30.000000', NULL, 1),
(4853359, 703717, 24913, '<td valign="top">A really nice composition and beautiful original idea. The image is way to overprocessed though...</td>', 'A really nice composition and beautiful original idea. The image is way to overprocessed though...', '2008-07-31 13:47:06.000000', NULL, 1),
(4853387, 703448, 83313, '<td valign="top">Almost had me fooled into thinking it was 6 boxes rather than 3. Nice job.</td>', 'Almost had me fooled into thinking it was 6 boxes rather than 3. Nice job.', '2008-07-31 14:05:42.000000', NULL, 1),
(4853407, 703704, 83313, '<td valign="top">I''m not a smoker muyself, but I appreciate the sentiment expressed here. The shots not very good, to be honest, but I give you credit for a good idea.</td>', 'I''m not a smoker muyself, but I appreciate the sentiment expressed here. The shots not very good, to be honest, but I give you credit for a good idea.', '2008-07-31 14:17:51.000000', NULL, 1),
(4853408, 702354, 73668, '<td valign="top">That is SOOO cute!!! Great Focus.</td>', 'That is SOOO cute!!! Great Focus.', '2008-07-31 14:18:40.000000', NULL, 1),
(4853409, 703653, 83313, '<td valign="top">Looks tough to fold a piece of cardboard like that.</td>', 'Looks tough to fold a piece of cardboard like that.', '2008-07-31 14:19:57.000000', NULL, 1),
(4853411, 703174, 90658, '<td valign="top">Atonal browns are nice for this shot.</td>', 'Atonal browns are nice for this shot.', '2008-07-31 14:21:32.000000', NULL, 1),
(4853412, 703715, 83313, '<td valign="top">Very creative.</td>', 'Very creative.', '2008-07-31 14:21:35.000000', NULL, 1),
(4853413, 703363, 90658, '<td valign="top">I''m having a real hard seeing this.  My mind knows what it should look like, but things seem noisy/grainy.</td>', 'I''m having a real hard seeing this.  My mind knows what it should look like, but things seem noisy/grainy.', '2008-07-31 14:23:45.000000', NULL, 1),
