(4861157, 703118, 60047, '<td valign="top">This is really fun.</td>', 'This is really fun.', '2008-08-03 10:54:25.000000', NULL, 1),
(4861159, 702074, 60047, '<td valign="top">You win the award for the most interestingly shaped box in the challenge! Great texture on the cardboard.</td>', 'You win the award for the most interestingly shaped box in the challenge! Great texture on the cardboard.', '2008-08-03 10:55:51.000000', NULL, 1),
