(4861166, 703650, 60047, '<td valign="top">I love the concept on this shot. I am fascinated by the detail in the feathers. But I am afraid you might get dinged for the lack of a box.</td>', 'I love the concept on this shot. I am fascinated by the detail in the feathers. But I am afraid you might get dinged for the lack of a box.', '2008-08-03 10:58:49.000000', NULL, 1),
(4861168, 703715, 60047, '<td valign="top">What an interesting answer to this challenge.</td>', 'What an interesting answer to this challenge.', '2008-08-03 10:59:28.000000', NULL, 1),
(4861172, 703717, 60047, '<td valign="top">The greens appear to be just a bit too saturated for me. Otherwise a great shot.</td>', 'The greens appear to be just a bit too saturated for me. Otherwise a great shot.', '2008-08-03 11:00:23.000000', NULL, 1),
(4861173, 703000, 60047, '<td valign="top">Plain and simple. Well done.</td>', 'Plain and simple. Well done.', '2008-08-03 11:00:47.000000', NULL, 1),
(4861176, 703214, 60047, '<td valign="top">I find the angle of the box and the choice of crop to be interesting. Wondering about the shallow DOF.</td>', 'I find the angle of the box and the choice of crop to be interesting. Wondering about the shallow DOF.', '2008-08-03 11:02:54.000000', NULL, 1),
(4861177, 703606, 60047, '<td valign="top">Great answer to the challenge. I hope you don''t get dinged for these being tubes and not boxes.</td>', 'Great answer to the challenge. I hope you don''t get dinged for these being tubes and not boxes.', '2008-08-03 11:03:59.000000', NULL, 1),
(4861178, 703708, 60047, '<td valign="top">I like the pattern and texture - I think more light might have helped this one.</td>', 'I like the pattern and texture - I think more light might have helped this one.', '2008-08-03 11:04:39.000000', NULL, 1),
(4861179, 702354, 60047, '<td valign="top">Love the model''s pose!</td>', 'Love the model''s pose!', '2008-08-03 11:05:15.000000', NULL, 1),
(4861181, 703456, 60047, '<td valign="top">This is different - and it works.</td>', 'This is different - and it works.', '2008-08-03 11:06:51.000000', NULL, 1),
(4861184, 702600, 60047, '<td valign="top">Quite different - and yet captivating.</td>', 'Quite different - and yet captivating.', '2008-08-03 11:07:58.000000', NULL, 1),
(4861187, 703684, 60047, '<td valign="top">I really like the creativity behind this shot. Great lines and patterns. Reminds me of <img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/21_F.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/21_F.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/21_F.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=48228" rel="nofollow" target="_blank">sherpet</a>''s work.</td>', 'I really like the creativity behind this shot. Great lines and patterns. Reminds me of  sherpet''s work.', '2008-08-03 11:08:50.000000', NULL, 1),
(4861188, 703069, 60047, '<td valign="top">Very clever. Great concept and execution.</td>', 'Very clever. Great concept and execution.', '2008-08-03 11:08:53.000000', NULL, 1),
(4861189, 702342, 60047, '<td valign="top">One of my favorites in this challenge - very creative.</td>', 'One of my favorites in this challenge - very creative.', '2008-08-03 11:08:55.000000', NULL, 1),
(4861190, 703184, 60047, '<td valign="top">One of my favorites. For those of us creatively challenged, I hope you give us a quick "how I did this."</td>', 'One of my favorites. For those of us creatively challenged, I hope you give us a quick "how I did this."', '2008-08-03 11:08:56.000000', NULL, 1),
(4861191, 703532, 60047, '<td valign="top">Beautiful light on the lion. Nice answer to this challenge.</td>', 'Beautiful light on the lion. Nice answer to this challenge.', '2008-08-03 11:08:58.000000', NULL, 1),
(4861192, 703533, 60047, '<td valign="top">Cool idea. Nice answer to the challenge.</td>', 'Cool idea. Nice answer to the challenge.', '2008-08-03 11:09:01.000000', NULL, 1),
(4861387, 703720, 65234, '<td valign="top">This is adorable!  I love the hat and the goggles and the angle to the shot is terrific.  Looks like great fun of the kind many parents won''t allow their kids anymore because it''s too dangerous.</td>', 'This is adorable!  I love the hat and the goggles and the angle to the shot is terrific.  Looks like great fun of the kind many parents won''t allow their kids anymore because it''s too dangerous.', '2008-08-03 13:54:29.000000', NULL, 1),
(4861388, 703184, 65234, '<td valign="top">Very well done!  EXtremely surreal with a simple box in an uncluttered space and ... a head!</td>', 'Very well done!  EXtremely surreal with a simple box in an uncluttered space and ... a head!', '2008-08-03 13:54:35.000000', NULL, 1),
(4861389, 703116, 65234, '<td valign="top">That must have taken forever to put together!  I like the backlight.  This would have been nice as a silhouette, too, but I think for this challenge you did the right thing to light the cardboard well enough for us to see some cardboard-y details.</td>', 'That must have taken forever to put together!  I like the backlight.  This would have been nice as a silhouette, too, but I think for this challenge you did the right thing to light the cardboard well enough for us to see some cardboard-y details.', '2008-08-03 13:54:37.000000', NULL, 1),
(4861524, 703710, 82840, '<td valign="top">nice!</td>', 'nice!', '2008-08-03 15:13:52.000000', NULL, 1),
(4861753, 703069, 67585, '<td valign="top">Holy creative idea batman</td>', 'Holy creative idea batman', '2008-08-03 17:41:08.000000', NULL, 1),
(4861757, 703757, 1031, '<td valign="top">I like the concept. I wish it had been aimed slightly to the right -- that bit of fence post bothers me a bit.</td>', 'I like the concept. I wish it had been aimed slightly to the right -- that bit of fence post bothers me a bit.', '2008-08-03 17:43:21.000000', NULL, 1),
(4861760, 703118, 1031, '<td valign="top">I like your lightwieght body armor ... I almost did something with boxing gloves myself, but I never got around to it.</td>', 'I like your lightwieght body armor ... I almost did something with boxing gloves myself, but I never got around to it.', '2008-08-03 17:45:09.000000', NULL, 1),
(4861761, 703704, 67585, '<td valign="top"><i></i></td>', '', '2008-08-03 17:45:22.000000', NULL, 1),
(4861774, 702074, 1031, '<td valign="top">The B&amp;W, high contrastm and graininess all work to help emphasize the progression of geometric shapes.</td>', 'The B&W, high contrastm and graininess all work to help emphasize the progression of geometric shapes.', '2008-08-03 17:51:54.000000', NULL, 1),
(4861781, 703277, 67585, '<td valign="top">Creepy!</td>', 'Creepy!', '2008-08-03 17:54:44.000000', NULL, 1),
(4861801, 703720, 1031, '<td valign="top">I don''t see this application on the "Most suitable for ..." list ;-)</td>', 'I don''t see this application on the "Most suitable for ..." list ;-)', '2008-08-03 18:01:49.000000', NULL, 1),
(4861811, 703659, 1031, '<td valign="top">I don''t know -- look ferocious enough to me ... :-)</td>', 'I don''t know -- look ferocious enough to me ... :-)', '2008-08-03 18:04:54.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4862036, 703745, 41211, '<td valign="top">Ha, we would never be able to leave our Christmas presents on the ground because our cats would do just this. Fun photo. 8 from me.</td>', 'Ha, we would never be able to leave our Christmas presents on the ground because our cats would do just this. Fun photo. 8 from me.', '2008-08-03 19:25:33.000000', NULL, 1),
