(4862258, 703518, 79357, '<td valign="top">Tacky and technically perfect</td>', 'Tacky and technically perfect', '2008-08-03 21:54:05.000000', NULL, 1),
(4862264, 703717, 79357, '<td valign="top">Fantastic! A little too much tone mapping for my taste, but I am sure many will like it.</td>', 'Fantastic! A little too much tone mapping for my taste, but I am sure many will like it.', '2008-08-03 21:55:20.000000', NULL, 1),
