(4862286, 703700, 79357, '<td valign="top">technically lots to work on but still a great shot</td>', 'technically lots to work on but still a great shot', '2008-08-03 21:59:16.000000', NULL, 1),
(4862293, 703676, 43774, '<td valign="top">Very cute, good colour and clarity. Did you remove some of the background? It looks a little choppy around the left ear.</td>', 'Very cute, good colour and clarity. Did you remove some of the background? It looks a little choppy around the left ear.', '2008-08-03 22:00:34.000000', NULL, 1),
(4862296, 703439, 43774, '<td valign="top">Love the idea, don''t love the blue tones, and you should have cloned out the wire holding up the boxes. But an excellent idea!</td>', 'Love the idea, don''t love the blue tones, and you should have cloned out the wire holding up the boxes. But an excellent idea!', '2008-08-03 22:01:17.000000', NULL, 1),
