(4862648, 703126, 23098, '<td valign="top">Well done, should be up at the top.</td>', 'Well done, should be up at the top.', '2008-08-04 00:06:02.000000', NULL, 1),
(4862649, 703717, 23098, '<td valign="top">The colors are vibrant and amazing. Good one.</td>', 'The colors are vibrant and amazing. Good one.', '2008-08-04 00:06:34.000000', NULL, 1),
